#include <vector>

using Grid = std::vector<std::vector<int>>;

int rowSum(const Grid& grid, std::size_t row)
{
    int total{ 0 };
    for (int value : grid[row])
    {
        total += value;
    }
    return total;
}

int columnSum(const Grid& grid, std::size_t column)
{
    int total{ 0 };
    for (const auto& row : grid)
    {
        total += row[column];
    }
    return total;
}

